/// <summary>
/// Bug 222247: CB326 - Header Charges for Shrink Wrap- Volumes based charges applied incorrectly.
/// </summary>
final class METSalesTableTotalWeightAndVolume_Delivered extends METSalesTableTotalWeightAndVolume
{
}

Method.Source:
/// <summary>
/// qty method
/// </summary>
/// <param name = "_salesLine">Sales order line record</param>
/// <returns>SO line delivered qty</returns>
SalesQty qty(SalesLine _salesLine)
{
    return (select sum(Qty) from CustPackingSlipTrans 
                           where CustPackingSlipTrans.inventTransId == _salesLine.inventTransId).Qty;
}
